struct Transition {
    Screen next;
    bool recreate = false;
    bool release = false;
};

private:
    study_round::Round initial_;
    std::optional<study_game::Game> game_;
    Screen screen_ = Screen::menu;
    bool armed_ = false;

if (decision.recreate) {
    game_.emplace(initial_);
    armed_ = false;
    const auto next = game_->round().end_reason() != study_round::EndReason::none
        ? Screen::finished : Screen::playing;
    report.screen_changed = next != screen_;
    report.game_replaced = true;
    screen_ = next;
    return report;
}

bool next_armed = armed_;
if (input.cancelled) next_armed = false;
if (!next_armed) {
    const bool cancelled = input.cancelled;
    input = {};
    input.cancelled = cancelled;
    if (released && !cancelled) next_armed = true;
}

const auto frame = game_->advance(seconds, input);
if (!frame) return std::nullopt;
armed_ = next_armed;
report.frame = *frame;
if (game_->round().end_reason() != study_round::EndReason::none) {
    screen_ = Screen::finished;
    report.screen_changed = true;
}
return report;

const auto update = app.advance(frame.dt, raw, confirm, back, released);
if (!update) return 1;
if (app.screen() == study_app::Screen::quitting) break;
// menu 경로는 메뉴를 그리고 continue한다.
const auto& game = *app.game();
const auto& round = game.round();

auto report = update->frame.value_or(study_loop::FrameReport{});
if (update->game_replaced) {
    report.board_changed = report.piece_changed = true;
    report_elapsed = 0;
}
if (report.board_changed || report.piece_changed || round.score() != view->score) {
    view = game.view();
    if (!view) return 1;
}

const study_mesh::Triangle menu_mesh{{
    {-0.25f, -0.4f}, {0.35f, 0.f}, {-0.25f, 0.4f}
}};
// 정점 버퍼와 VAO는 한 번 만들고 메뉴 프레임마다 재사용한다.

auto beginSingleRound = [&]() {
    auto next = std::make_unique<Game>(sessionSeed);
    gameSingle = std::move(next);
    accumulator = 0.0f;
    s_pendingInput = 0;
    s_leftHoldTicks = s_rightHoldTicks = 0;
    coLocal = {};
    shakeLeft = {};
    if (recording) { replay.frames.clear(); replay.seed = sessionSeed; }
    app = AppMode::Single;
};
